.pi-icon-text {
	color: #111827;
	font-weight: 600;
}

.pi-budget {
	color: #059669;
	font-weight: 700;
}

.pi-bullet {
	color: #cbd5e1;
}

.item-summary {
	display: flex;
	align-items: center;
	gap: 6px;
	font-size: 12px;
	color: #475569;
	flex-shrink: 0;
}

.is-label {
	font-weight: 500;
}

.is-value {
	font-weight: 600;
	color: #111827;
}

.is-bold {
	font-weight: 800;
}

