	align-items: center;
	gap: 6px;
	padding: 6px 14px;
	background: #ffffff;
	border: 1px solid #cbd5e1;
	border-radius: 6px;
	font-size: 12px;
	font-weight: 600;
	color: #334155;
	cursor: pointer;
	transition: all 0.15s ease;
}

.btn-outline:hover {
	background: #f8fafc;
	border-color: #94a3b8;
	color: #0f172a;
}

.btn-outline.active {
	background: #eff6ff;
	border-color: #2563eb;
	color: #2563eb;
}

/* Line Items Expandable Panel */
.line-items-panel {
	background: #ffffff;
	border-bottom: 1px solid #e2e8f0;
	padding: 0 20px 16px 20px; /* Removed top padding so sticky header touches the top */
	max-height: 190px; /* ~4 rows + header */
	overflow-y: auto;
}

.li-table {
	width: 100%;
	border-collapse: separate; /* Changed from collapse to separate to make sticky borders work better */
	border-spacing: 0;
	font-size: 12px;
	text-align: left;
}

.li-table th {
	background: #f8fafc;
	color: #64748b;
	font-weight: 700;
	padding: 12px 12px; /* Slightly thicker padding to compensate for removed panel padding */
	border-bottom: 1px solid #e2e8f0;
	text-transform: uppercase;
	letter-spacing: 0.5px;
	font-size: 11px;
	position: sticky;
	top: 0;
	z-index: 10;
}

/* Create a fake border for the sticky header since border-collapse is separate */
.li-table th::after {
	content: "";
	position: absolute;
	left: 0;
	right: 0;
	bottom: 0;
	border-bottom: 1px solid #e2e8f0;
}

.li-table td {
	padding: 10px 12px;
	border-bottom: 1px solid #f1f5f9;
	color: #1e293b;
}

.li-table tr:last-child td {
	border-bottom: none;
}

.li-id {
	font-family: "Courier New", monospace;
	font-weight: 700;
	color: #2563eb;
}

.li-link {
	color: #2563eb;
	text-decoration: none;
	font-weight: 600;
	transition: all 0.15s ease;
}

.li-link:hover {
	color: #1d4ed8;
	text-decoration: underline;
}

